test('provider-disabled Studio source flow is honest and makes no extraction attempt',async({page},info)=>{type ObservedTraffic={phase:'adversarial'|'controlled';url:string;method:string};const observedTraffic:ObservedTraffic[]=[];let phase:ObservedTraffic['phase']='adversarial';page.on('request',request=>{if(isSourceProviderTraffic(request))observedTraffic.push({phase,url:request.url(),method:request.method()});});await page.route('**/functions/v1/enterprise-intelligence/studio.evidence.extract?observer_probe=1',route=>route.abort('blockedbyclient'));await open(page,'?mode=direct&sourceJourney=1&sourceProvider=disabled');const prematureSampleCount=observedTraffic.filter(item=>item.phase==='adversarial').length;expect(prematureSampleCount).toBe(0);await page.evaluate(async()=>{await new Promise<void>(resolve=>{setTimeout(()=>{void fetch('/functions/v1/enterprise-intelligence/studio.evidence.extract?observer_probe=1',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({commandType:'studio.evidence.extract',syntheticObserverProbe:true})}).catch(()=>undefined).finally(resolve);},25);});});const adversarialDelayedRequests=observedTraffic.filter(item=>item.phase==='adversarial');expect(adversarialDelayedRequests).toHaveLength(1);const lateTrafficGateRejected=adversarialDelayedRequests.length>0;expect(lateTrafficGateRejected).toBe(true);phase='controlled';await open(page,'?mode=direct&sourceJourney=1&sourceProvider=disabled');const intake=page.getByRole('region',{name:'Upload, extract, and review Studio sources'});await expect(intake.getByText('Provider extraction is unavailable: provider disabled. No provider call will be attempted.')).toBeVisible();await intake.getByLabel('Exact Studio bundle for extraction').selectOption('00000032-0000-4000-8000-000000000032');await expect(intake.getByRole('button',{name:'Run governed Studio extraction'})).toBeDisabled();await page.waitForLoadState('networkidle');const countAtQuiescence=observedTraffic.filter(item=>item.phase==='controlled').length;const sourceExtractionInvocationCount=await page.evaluate(()=>(window as any).__studioSourceExtractionCalls);await page.waitForTimeout(250);expect(observedTraffic.filter(item=>item.phase==='controlled')).toHaveLength(countAtQuiescence);expect(sourceExtractionInvocationCount).toBe(0);expect(await page.evaluate(()=>(window as any).__studioSourceExtractionCalls)).toBe(sourceExtractionInvocationCount);await page.close();const providerOrExtractionRequestCount=observedTraffic.filter(item=>item.phase==='controlled').length;expect(providerOrExtractionRequestCount).toBe(0);expect(page.isClosed()).toBe(true);markerC(info,'STUDIO-TR-001','provider-disabled-zero-call',{providerExtractionEnabled:false,prematureSampleCount,adversarialDelayedRequestCount:adversarialDelayedRequests.length,lateTrafficGateRejected,sourceExtractionInvocationCount,providerOrExtractionRequestCount,observationWindow:'clean-navigation-through-page-close',quiescenceWindowMs:250,pageClosedBeforeEvidence:true,existingCommittedEvidenceReadable:true});});

