test('loading, empty, processing, offline, malformed and bounded large-source views fail safely',async({page},info)=>{await navigate(page,'/tests/browser/studioPrB/harness.html?state=loading');await expect(page.getByLabel('Loading Studio artifact')).toBeVisible();marker(info,'STUDIO-TR-009','loading-state-announced-before-projection','STUDIO-LOADING-01',{viewState:'loading',falseSuccess:false});await expect(page.getByText('Current committed artifact loaded.')).toBeVisible();await open(page,'?state=empty');await expect(page.getByText('No accepted governed Studio handoffs are available.')).toBeVisible();await expect(page.getByText('No committed artifact')).toBeVisible();marker(info,'STUDIO-TR-009','empty-state-has-no-fabricated-artifact','STUDIO-EMPTY-01',{viewState:'empty',artifactCount:0});await open(page,'?state=processing');let handoffs=page.getByRole('region',{name:'Assess → Studio handoffs'});await handoffs.getByRole('button',{name:'Request handoff'}).click();let dialog=page.getByRole('dialog');await dialog.getByRole('button',{name:'Confirm'}).click();await expect(dialog.getByRole('button',{name:'Committing…'})).toBeVisible();await handoffs.getByRole('tab',{name:/Outbox/}).click();await expect(handoffs.getByText('reviewer ready',{exact:true})).toBeVisible();marker(info,'HANDOFF-001','processing-state-waits-for-committed-reload','HANDOFF-PROCESSING-01',{viewState:'processing_then_committed',falseSuccess:false});await open(page,'?state=offline');await expect(page.getByText('Offline. Committed content remains visible; mutations are blocked.').first()).toBeVisible();marker(info,'STUDIO-TR-009','offline-state-blocks-mutations','STUDIO-OFFLINE-01',{viewState:'offline',domainMutationCount:0});await navigate(page,'/tests/browser/studioPrB/harness.html?state=malformed');await expect(page.getByText('Artifact discovery is unavailable. Other authorized Studio projections remain usable.',{exact:true})).toBeVisible();await expect(page.getByText('<script>hostile</script>')).toHaveCount(0);marker(info,'STUDIO-TR-009','malformed-artifact-result-isolated-without-hostile-render','STUDIO-MALFORMED-01',{viewState:'artifact_projection_unavailable',otherAuthorizedProjectionsUsable:true,hostileRenderCount:0});await open(page,'?mode=direct&state=large');await expect(page.getByText(/^Bounded Studio source /)).toHaveCount(50);await expect(page.getByText('Page 1 of 3 · 125 selected')).toBeVisible();await page.getByRole('button',{name:'Next sources'}).click();await expect(page.getByText('Page 2 of 3 · 125 selected')).toBeVisible();marker(info,'STUDIO-TR-001','large-source-list-bounded-and-paginated','STUDIO-LARGE-125',{pageSize:50,totalSelectedSourceCount:125,sourcePageCount:3,silentTruncation:false});});

test('existing read-only legacy authority loads its artifact without optional PR B capabilities',async({page},info)=>{await open(page,'?mode=direct&legacy=1&state=legacy-read-only');const editor=page.getByRole('region',{name:'Structured section editor'});await expect(editor.getByLabel('Section title')).toHaveValue('Backfilled legacy control brief');await expect(editor.getByLabel('Section body')).toHaveValue('Safely retained legacy narrative.');await expect(page.getByText('Content v1')).toBeVisible();await expect(page.getByText(/Studio authority is unavailable/)).toHaveCount(0);await expect(page.getByText(/Current committed artifact loaded/)).toBeVisible();const restricted=['studio.artifacts.read'];marker(info,'COMPAT-003','backfilled-legacy-artifact-safe-structured-read','LEGACY-STUDIO-BACKFILL-01',{artifactVersion:1,legacyProjectionRetained:true,safeStructuredFallback:true,optionalPrBProjectionCalled:false},restricted);});

test('wrong-workspace handoff is non-disclosing and artifact lifecycle controls stay server gated',async({page},info)=>{await navigate(page,'/tests/browser/studioPrB/harness.html?handoff=wrong-workspace');await expect(page.getByText('Artifact discovery is unavailable. Other authorized Studio projections remain usable.',{exact:true})).toBeVisible();await expect(page.getByText('Approved AP assessment v3')).toHaveCount(0);marker(info,'HANDOFF-008','wrong-workspace-nondisclosure','HANDOFF-WRONG-WORKSPACE-01',{disclosedTargetCount:0,safeError:'RESOURCE_NOT_AVAILABLE',failureIsolation:'artifact_projection_only'});await open(page);const artifactWorkspace=page.getByTestId('studio-artifact-workspace');for(const name of ['Submit for review','Assign reviewer','Approve review','Request changes','Reject review','Final approve','Final reject'])await expect(artifactWorkspace.getByRole('button',{name,exact:true})).toBeVisible();marker(info,'STUDIO-TR-010','review-reject-approval-controls-server-gated','STUDIO-LIFECYCLE-01',{lifecycle:'draft',separationOfDuty:'fresh_server_eligibility_required'});});

test('A11Y-003/A11Y-004 Studio route has zero serious or critical axe findings and no mobile overflow',async({page},info)=>{await open(page);const findings=await new AxeBuilder({page}).withTags(['wcag2a','wcag2aa','wcag21aa']).analyze();const severe=findings.violations.filter(item=>item.impact==='serious'||item.impact==='critical');expect(severe).toEqual([]);marker(info,'A11Y-003','axe-serious-critical-zero','STUDIO-PR-B-HARNESS',{seriousCriticalFindings:0});const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>document.documentElement.clientWidth);expect(overflow).toBe(false);await page.evaluate(()=>{document.documentElement.style.zoom='2';});const zoomOverflow=await page.evaluate(()=>document.documentElement.scrollWidth>document.documentElement.clientWidth);expect(zoomOverflow).toBe(false);marker(info,'A11Y-004','responsive-overflow-zero-at-200-percent','STUDIO-PR-B-HARNESS',{horizontalOverflow:false,zoomPercent:200});});

test('PERF-001 cached route loaded governed projection median is below 2.5 seconds',async({page},info)=>{await open(page);const samples:number[]=[];for(let index=0;index<3;index++){await page.reload({waitUntil:'domcontentloaded'});await page.locator('[data-testid="studio-artifact-workspace"][data-studio-usable="true"][data-studio-projection-state="artifact-ready"]').waitFor({state:'visible'});samples.push(await page.evaluate(()=>performance.now()));}const ordered=[...samples].sort((a,b)=>a-b);const median=ordered[1];expect(median).toBeLessThan(2500);marker(info,'PERF-001','cached-studio-loaded-governed-projection-under-2500ms','STUDIO-PR-B-HARNESS',{usableSelector:'[data-testid="studio-artifact-workspace"][data-studio-usable="true"][data-studio-projection-state="artifact-ready"]',loadedState:'artifact-ready',warmupRuns:1,sampleCount:3,samplesMs:samples.map(value=>Math.round(value)),medianMs:Math.round(median),budgetMs:2500});});
